              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.cognitiveservices/accounts'\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n| extend acctKind   = tostring(kind)\n| extend isModelHost = (acctKind in~ ('OpenAI','AIServices'))\n| extend skuName    = tostring(sku.name)\n| extend identityType = tostring(identity.type)\n| extend pna        = tostring(properties.publicNetworkAccess)\n| extend localAuthDisabled = tobool(properties.disableLocalAuth)\n| extend subdomain  = tostring(properties.customSubDomainName)\n| extend restrictOutbound = tobool(properties.restrictOutboundNetworkAccess)\n| extend netDefault = tostring(properties.networkAcls.defaultAction)\n| extend ipRuleCount = toint(array_length(todynamic(properties.networkAcls.ipRules)))\n| extend vnetRuleCount = toint(array_length(todynamic(properties.networkAcls.virtualNetworkRules)))\n| extend cmkSource  = tostring(properties.encryption.keySource)\n| extend allowProjectMgmt = tobool(properties.allowProjectManagement)\n| extend state      = tostring(properties.provisioningState)\n| extend created    = todatetime(properties.dateCreated)\n| extend endpoint   = tostring(properties.endpoint)\n| extend isMigrated = tobool(properties.isMigrated)\n| extend peCount    = toint(array_length(todynamic(properties.privateEndpointConnections)))\n| extend KindLabel  = case(\n      acctKind =~ 'OpenAI',     'Azure OpenAI',\n      acctKind =~ 'AIServices', 'Microsoft Foundry (AI Services)',\n      acctKind =~ 'CognitiveServices', 'Cognitive Services (multi-service)',\n      acctKind)\n| extend IssueList = array_concat(\n    iff(localAuthDisabled != true,                      pack_array('API key (local) auth enabled - prefer Entra ID'), dynamic([])),\n    iff(pna =~ 'Enabled' and peCount == 0,              pack_array('Public network access with no private endpoint'), dynamic([])),\n    iff(pna =~ 'Enabled' and netDefault !~ 'Deny',      pack_array('Network ACLs allow all traffic'), dynamic([])),\n    iff(isempty(identityType) or identityType =~ 'None', pack_array('No managed identity'), dynamic([])),\n    iff(isModelHost and isempty(subdomain),             pack_array('No custom subdomain - Entra ID auth unavailable'), dynamic([])),\n    iff(isempty(cmkSource) or cmkSource =~ 'Microsoft.CognitiveServices', pack_array('Microsoft-managed keys (no CMK)'), dynamic([])),\n    iff(isModelHost and restrictOutbound != true,       pack_array('Outbound network access unrestricted'), dynamic([])),\n    iff(state !~ 'Succeeded',                           pack_array(strcat('Provisioning state: ', state)), dynamic([]))\n  )\n| extend IssueCount = array_length(IssueList)\n| extend Issues     = strcat_array(IssueList, ' | ')\n| extend Severity = case(\n      IssueCount >= 6, 'Critical',\n      IssueCount >= 4, 'High',\n      IssueCount >= 2, 'Medium',\n      IssueCount >= 1, 'Low',\n                       'Healthy')\n| extend SeverityRank = case(Severity == 'Critical', 0, Severity == 'High', 1, Severity == 'Medium', 2, Severity == 'Low', 3, 4)\n| project\n    Account = name,\n    Subscription,\n    Kind = KindLabel,\n    ['Resource group'] = resourceGroup,\n    Region = location,\n    SKU = skuName,\n    State = state,\n    Severity,\n    Findings = toint(IssueCount),\n    Detail = iff(IssueCount == 0, 'No findings', Issues),\n    SeverityRank,\n    ResourceId = id\n| order by Findings desc, SeverityRank asc, Account asc\n| project-away SeverityRank",
              "size": 2,
              "title": "All AI accounts and findings",
