              ],
              "gridSettings": {
                "rowLimit": 1000,
                "filter": true,
                "sortBy": [
                  {
                    "itemKey": "Capacity",
                    "sortOrder": 2
                  }
                ]
              }
            },
            "name": "ModelDeployments"
          },
          {
            "content": {
              "version": "KqlItem/1.0",
              "query": "{\"version\":\"ARMEndpoint/1.0\",\"method\":\"GET\",\"path\":\"subscriptions/{AccountSubscription}/providers/Microsoft.CognitiveServices/locations/{AccountRegion}/models\",\"headers\":[],\"urlParams\":[{\"key\":\"api-version\",\"value\":\"2024-10-01\"}],\"batchDisabled\":false,\"transformers\":[{\"type\":\"jsonpath\",\"settings\":{\"tablePath\":\"$.value[?(@.kind == '{AccountKind}' && @.name == '{SelectedDeploymentFormat}.{SelectedDeploymentModel}.{SelectedDeploymentVersion}')]\",\"columns\":[{\"path\":\"name\",\"columnid\":\"Deployment\",\"columnType\":\"string\",\"substringRegexMatch\":\"^.*$\",\"substringReplace\":\"{SelectedDeploymentName}\"},{\"path\":\"model.name\",\"columnid\":\"Model\",\"columnType\":\"string\"},{\"path\":\"model.version\",\"columnid\":\"Version\",\"columnType\":\"string\"},{\"path\":\"model.format\",\"columnid\":\"Format\",\"columnType\":\"string\"},{\"path\":\"name\",\"columnid\":\"SKU\",\"columnType\":\"string\",\"substringRegexMatch\":\"^.*$\",\"substringReplace\":\"{SelectedDeploymentSku}\"},{\"path\":\"model.lifecycleStatus\",\"columnid\":\"Lifecycle\",\"columnType\":\"string\"},{\"path\":\"model.deprecation.inference\",\"columnid\":\"Inference retirement\",\"columnType\":\"datetime\"},{\"path\":\"model.deprecation.fineTune\",\"columnid\":\"Fine-tune retirement\",\"columnType\":\"datetime\"}]}}]}",
              "size": 1,
