                "formatters": [
                  {
                    "columnMatch": "Lifecycle",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "colors",
                      "thresholdsGrid": [
                        {
                          "operator": "is Empty",
