  pack_array('Datastores use access keys - prefer identity'), dynamic([])),\n    iff(cmkEnabled != true,                       pack_array('No customer-managed key encryption'), dynamic([])),\n    iff(isempty(identityType) or identityType =~ 'None', pack_array('No managed identity'), dynamic([])),\n    iff(softDelete != true,                       pack_array('Soft delete not enabled'), dynamic([])),\n    iff(v1Legacy == true,                         pack_array('v1 legacy mode enabled'), dynamic([])),\n    iff(wsKind =~ 'Project' and isempty(hubId),   pack_array('Project not linked to a hub'), dynamic([])),\n    iff(state !~ 'Succeeded',                     pack_array(strcat('Provisioning state: ', state)), dynamic([]))\n  )\n| extend IssueCount = array_length(IssueList)\n| extend Issues     = strcat_array(IssueList, ' | ')\n| extend Severity = case(\n      IssueCount >= 6, 'Critical',\n      IssueCount >= 4, 'High',\n      IssueCount >= 2, 'Medium',\n      IssueCount >= 1, 'Low',\n                       'Healthy')\n| extend SeverityRank = case(Severity == 'Critical', 0, Severity == 'High', 1, Severity == 'Medium', 2, Severity == 'Low', 3, 4)\n| summarize\n    Hubs = countif(wsKind =~ 'Hub'),\n    Projects = countif(wsKind =~ 'Project'),\n    Other = countif(wsKind !~ 'Hub' and wsKind !~ 'Project'),\n    AtRisk = countif(IssueCount > 0),\n    NoIsolation = countif(isolation =~ 'Disabled'),\n    KeyDatastores = countif(authMode =~ 'accesskey')\n| extend Tiles = pack_array(\n    pack('Metric', 'AI Hubs',                  'Value', Hubs,          'Rank', 1),\n    pack('Metric', 'AI Projects',              'Value', Projects,      'Rank', 2),\n    pack('Metric', 'Other ML workspaces',      'Value', Other,         'Rank', 3),\n    pack('Metric', 'Workspaces with findings', 'Value', AtRisk,        'Rank', 4),\n    pack('Metric', 'Managed VNet disabled',    'Value', NoIsolation,   'Rank', 5),\n    pack('Metric', 'Datastores using keys',    'Value', KeyDatastores, 'Rank', 6))\n