            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "servicehealthresources\n| where type =~ 'microsoft.resourcehealth/events'\n| extend\n    eventType = tostring(properties.EventType),\n    eventSubType = tostring(properties.EventSubType)\n| where eventType == 'HealthAdvisory' and eventSubType == 'Retirement'\n| extend\n    status = tostring(properties.Status),\n    retirementTitle = tostring(properties.Title),\n    trackingId = tostring(properties.TrackingId),\n    retirementSummary = tostring(properties.Summary),\n    retirementDate = todatetime(tolong(properties.ImpactMitigationTime))\n| where isnotnull(retirementDate)\n| extend retirementText = tolower(strcat(retirementTitle, ' ', retirementSummary))\n| where retirementText contains 'azure ai'\n    or retirementText contains 'microsoft foundry'\n    or retirementText contains 'azure openai'\n    or retirementText contains 'machine learning'\n    or retirementText contains 'cognitive services'\n    or retirementText contains 'ai services'\n    or retirementText contains 'prompt flow'\n    or retirementText contains 'model inference'\n    or retirementText contains 'agent service'\n    or retirementText contains 'qnamaker'\n    or retirementText contains 'qna maker'\n    or retirementText contains 'language understanding'\n    or retirementText contains 'computer vision'\n    or retirementText contains 'custom vision'\n    or retirementText contains 'form recognizer'\n    or retirementText contains 'document intelligence'\n    or retirementText contains 'speech service'\n    or retirementText contains 'content moderator'\n    or retirementText contains 'anomaly detector'\n    or retirementText contains 'personalizer'\n    or retirementText contains 'metrics advisor'\n    or retirementText contains 'azure bot'\n    or retirementText contains 'cognitive search'\n    or retirementText contains 'azure ai search'\n| extend\n    cleanSummary = trim(' ', replace_regex(retirementSummary, '<[^>]+>', ' ')),\n    deadlineStatus = iff(retirementDate < now(), 'Past due', 'Upcoming')\n| project\n    ['Tracking ID'] = trackingId,\n    Subscription = subscriptionId,\n    Status = status,\n    ['Deadline status'] = deadlineStatus,\n    Retirement = retirementTitle,\n    Summary = cleanSummary,\n    ['Retirement date'] = retirementDate\n| order by ['Retirement date'] asc",
