        "items": [
          {
            "type": 1,
            "content": {
              "json": "## Azure Advisor and Resource Health\r\n\r\nReads the `advisorresources` and `healthresources` tables for AI accounts and ML\r\nworkspaces. Empty panels mean no recommendations or health events exist for the\r\nselected resources - a valid healthy result, not an error."
            },
            "name": "adHead"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "advisorresources\n| where type =~ 'microsoft.advisor/recommendations'\n| extend targetId = tolower(tostring(properties.resourceMetadata.resourceId))\n| join kind=inner (\n    resources\n    | where type =~ 'microsoft.cognitiveservices/accounts'\n       or type =~ 'microsoft.machinelearningservices/workspaces'\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n    | project targetId = tolower(id), rName = name, rSubscription = Subscription, rRg = resourceGroup, rType = type\n  ) on targetId\n| project\n    Resource = rName,\n    Subscription = rSubscription,\n    ['Resource group'] = rRg,\n    Category = tostring(properties.category),\n    Impact = tostring(properties.impact),\n    Problem = tostring(properties.shortDescription.problem),\n    Solution = tostring(properties.shortDescription.solution),\n    ResourceId = targetId\n| order by Impact asc, Resource asc",
              "size": 2,
              "title": "Advisor recommendations",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
