            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "healthresources\n| where type =~ 'microsoft.resourcehealth/availabilitystatuses'\n| extend targetId = tolower(tostring(properties.targetResourceId))\n| join kind=inner (\n    resources\n    | where type =~ 'microsoft.cognitiveservices/accounts'\n       or type =~ 'microsoft.machinelearningservices/workspaces'\n    | extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n    | join kind=leftouter (\n    resourcecontainers\n    | where type =~ 'microsoft.resources/subscriptions'\n    | project subscriptionId, Subscription = name\n  ) on subscriptionId\n    | project targetId = tolower(id), rName = name, rSubscription = Subscription, rRg = resourceGroup\n  ) on targetId\n| project\n    Resource = rName,\n    Subscription = rSubscription,\n    ['Resource group'] = rRg,\n    Availability = tostring(properties.availabilityState),\n    Summary = tostring(properties.summary),\n    ['Since'] = todatetime(properties.occuredTime),\n    ResourceId = targetId\n| order by Availability asc",
